class PipelineEvaluator:
    """
    CI workflow DAG generation engine.
    """
    def __init__(self):
        pass

    def generate_workflow(self, dependencies: dict) -> dict:
        """
        Given dependencies mapping job IDs to lists of prerequisite job IDs,
        return a workflow dictionary mapping job names 'job_{i}' to config dictionaries.
        """
        # Normalize inputs: str/int keys, missing entries, and non-list parents.
        deps = {}
        for job_id, parents in dependencies.items():
            job_id = int(job_id)
            if parents is None:
                parents = []
            elif isinstance(parents, (int, float)):
                parents = [parents]
            else:
                parents = list(parents)
            deps[job_id] = [int(p) for p in parents]

        job_ids = sorted(deps.keys())
        name_of = {jid: "job_" + str(jid) for jid in job_ids}

        # Topological sort (Kahn's algorithm).
        remaining = {jid: set(deps[jid]) for jid in job_ids}
        layer = {jid: 0 for jid in job_ids}
        ready = [jid for jid in job_ids if not remaining[jid]]
        processed = []
        while ready:
            current = ready.pop()
            processed.append(current)
            for jid in job_ids:
                if current in remaining[jid]:
                    remaining[jid].discard(current)
                    if not remaining[jid]:
                        ready.append(jid)

        # Any unresolved jobs indicate a cycle or a reference to an unknown job.
        unresolved = set(jid for jid in job_ids if remaining[jid])
        for jid in sorted(unresolved, key=lambda x: len(deps[x])):
            known = [p for p in deps[jid] if p in layer and p not in unresolved]
            if known:
                layer[jid] = max(layer[p] for p in known) + 1

        workflow = {}
        for jid in job_ids:
            workflow[name_of[jid]] = {
                "needs": [name_of[p] for p in deps[jid]],
                "env": {"LAYER": layer[jid]},
            }
        return workflow

